-- CNIGS commune reference. Provenance and regeneration: docs/report-territories.md.
create table private.report_communes (
 code text primary key, name text not null,
 department_code text not null, department_name text not null
);
create index report_communes_department_idx on private.report_communes(department_code);
create table private.report_commune_boundaries (
 id bigint generated always as identity primary key,
 commune_code text not null references private.report_communes(code),
 exterior polygon not null, holes polygon[] not null default '{}',
 bounds box generated always as (box(exterior)) stored
);
create index report_commune_boundaries_bounds_idx on private.report_commune_boundaries using gist(bounds);
create index report_commune_boundaries_commune_idx on private.report_commune_boundaries(commune_code);
alter table private.report_communes enable row level security;
alter table private.report_commune_boundaries enable row level security;
revoke all on private.report_communes,private.report_commune_boundaries from public,anon,authenticated;
